SELECT a.* , b.FILE_PATH , b.FILE_NEW_NAME FROM TB_PRODUCT a LEFT JOIN TB_FILE b ON b.MENU_CD = #{data.menuCd} AND b.PK_ID = a.PRODUCT_ID AND b.FILE_DV_CD = #{data.fileDvCd}
PRODUCT_NAME LIKE CONCAT('%', #{data.productName}, '%')
AND PRODUCT_CD LIKE CONCAT('%', #{data.productCd}, '%')
AND DP_STATUS = #{data.dpStatus}
AND STATUS = #{data.status}
AND a.REG_DT >= DATE_FORMAT(REPLACE(#{data.strDt}, "-", ""), '%Y/%m/%d 00:00:00')
AND a.REG_DT <= DATE_FORMAT(REPLACE(#{data.endDt}, "-", ""), '%Y/%m/%d 23:59:59')
ORDER BY a.REG_DT DESC LIMIT #{pageable.offset}, #{data.cntPerPage}

SELECT COUNT(*) AS CNT FROM TB_PRODUCT a LEFT JOIN TB_FILE b ON b.MENU_CD = #{menuCd} AND b.PK_ID = a.PRODUCT_ID AND b.FILE_DV_CD = #{fileDvCd}
1=1
AND PRODUCT_NAME LIKE CONCAT('%', #{productName}, '%')
AND PRODUCT_CD = #{productCd}
AND STATUS LIKE CONCAT('%', #{status}, '%')
