INSERT INTO TB_PRODUCT (
    PRODUCT_NAME
    , PRODUCT_CD
    , PRICE
    , DIS_PRICE
    , DIS_RATE
    , CONTENT
    , SUMMATION
    , STOCKS
    , SALES
    , STATUS
    , DP_STATUS
    , WATT
    , DELIVERY_FEE
    , FREE_DELIVERY_FEE
    , DEL_YN
    , REG_ID
    , REG_DT
    , MOD_ID
    , MOD_DT
)
VALUES (
    #{productName}
    , CONCAT('L',REPLACE(SUBSTRING(UUID(),1,15),'-',''))
    , #{price}
    , #{disPrice}
    , #{disRate}
    , #{content}
    , #{summation}
    , #{stocks}
    , #{sales}
    , #{status}
    , #{dpStatus}
    , #{watt}
    , #{deliveryFee}
    , #{freeDeliveryFee}
    , #{delYn}
    , #{regId}
    , NOW()
    , #{modId}
    , NOW()
)

mapper.update:
UPDATE
	TB_PRODUCT
SET
	MOD_ID = #{modId}
	, MOD_DT = NOW()

    , PRODUCT_NAME = #{productName}


    , PRODUCT_CD = #{productCd}


    , PRICE = #{price}


    , DIS_PRICE = #{disPrice}


    , CONTENT = #{content}


    , SUMMATION = #{summation}


    , STOCKS = #{stocks}


    , SALES = #{sales}


    , STATUS = #{status}


    , DP_STATUS = #{dpStatus}


    , WATT = #{watt}


    , DELIVERY_FEE = #{deliveryFee}


    , FREE_DELIVERY_FEE = #{freeDeliveryFee}

WHERE
	PRODUCT_ID = #{productId}

UPDATE TB_PRODUCT
SET 
	DEL_YN = #{delYn}
WHERE
	PRODUCT_ID = #{productId}

